@js:
(function() {
    var param = '';
    try {
        var sourceVal = source.getVariable();
        if (sourceVal != null && String(sourceVal).length > 0) {
            param = '&source=' + encodeURIComponent(String(sourceVal));
        }
    } catch(e){}
    return '/searchs?page={{page}}&key={{key}}' + param;
})()

