ruleContent.payAction:
(function(){
    java.setContent(java.ajax("https://masiro.me" + baseUrl));
    let costUrl = "https://masiro.me/admin/pay";
    let chapterBody = `type=${java.getString("class.type@value")}&object_id=${java.getString("class.object_id@value")}&cost=${java.getString("class.cost@value")}`;
    let headers = {
        "X-CSRF-TOKEN": java.getString("class.csrf@value"),
        "X-Requested-With": "XMLHttpRequest",
        "User-Agent": "Mozilla/5.0 (Linux; Android 14)",
        "Referer": String("https://masiro.me" + baseUrl)
    };
    let responseBody = java.post(costUrl, chapterBody, headers).body();
    if(JSON.parse(responseBody).code === 1) {
        java.longToast(JSON.parse(responseBody).msg);
        return true;
    } else {
        java.longToast(JSON.parse(responseBody).msg || "支付失败");
        return false;
    }
})()

