        yn = yn => yn ? '启用' : '禁用';
        $$ = (type) => {
            t2 = type;
            if (type == '全部') {
                type = "推荐"
                for (key of Arr.slice(1))
                    $[key] = !$[type];
            }
            login('发现设置：\n【' + t2 + '】 ' + yn($[type]) + ' => ' + yn($[type] = !$[type]));
            return setv($);
        }
        $ = function() {
            try {
                return JSON.parse(source.getVariable());
            } catch (err) {
                return null;
            }
        }();
        if ($ == null) {
            $ = {};
            for (key of Arr)
                $[key] = true;
            setv($);
        }
    }
}

